"""Exact k-point correlation MMD for token processes generated by a CountChain model
(CoMB, its dephased twin, ClassicalHMM).

The model emits one token c_beta in 0..K-1 per round through instruments Lambda_{beta,c}
(linear maps on the memory vector, summing to a trace-preserving map T_beta).  The loss
compares low-order marginals of the token process with those of the data:

    windows   W_k(t) = law of (c_t, ..., c_{t+k-1}),      k = 1..kmax, every t
    pairs     P(t, s) = law of (c_t, c_s),                s - t in a set of lags

through the MMD of a product kernel built from a positive semidefinite token kernel G:

    MMD^2(p, q) = (p - q)^T (G x ... x G) (p - q),
    L = sum_k lam_k mean_t MMD^2(W_k(t)) + lam_pair mean_{(t,s)} MMD^2(P(t,s)).

This is the MMD of a kernel on sequences, K(c, c') = sum_k lam_k sum_t prod_j G[c_{t+j}, c'_{t+j}]
+ lam_pair sum_{(t,s)} G[c_t, c'_t] G[c_s, c'_s]; it sees exactly the k-point correlations of the
process, nothing else.  For the model every marginal is exact:

    W_k(t)(a_1..a_k) = tr[ Lambda_{t+k-1,a_k} ... Lambda_{t,a_1} r_{t-1} ],   r_t = T_t r_{t-1},
    P(t,s)(a, b)     = tr[ Lambda_{s,b} T_{s-1} ... T_{t+1} Lambda_{t,a} r_{t-1} ],

so no sampling, no frequencies and no teacher forcing enter; the gradient is exact as well,
by reverse mode through the same products and then pixel_instrument_vjp of the model.
Complex gradient convention of the package: G = dL/dRe + i dL/dIm.
"""
import json, pathlib, time
import numpy as np

from .train import Adam, lr_at


# --------------------------------------------------------------------------- token kernel
def token_kernel(K, kind="stroke", kappa=2.0, rho_pen=0.3):
    """Positive semidefinite K x K kernel on tokens.
    kind="delta":  identity (plain squared distance between laws).
    kind="stroke": tokens c = pen * 8 + dir with 8 compass directions and pen in {down, up}
                   (K must be 16): von Mises kernel exp(kappa (cos(dtheta) - 1)) on the direction,
                   times a pen kernel [[1, rho], [rho, 1]].  Kronecker product of PSD kernels is PSD."""
    if kind == "delta":
        return np.eye(K)
    if kind != "stroke" or K != 16:
        raise ValueError("stroke kernel needs K = 16 tokens (8 directions x pen state)")
    th = np.arange(8) * (np.pi / 4)
    Gdir = np.exp(kappa * (np.cos(th[:, None] - th[None, :]) - 1.0))
    Gpen = np.array([[1.0, rho_pen], [rho_pen, 1.0]])
    G = np.kron(Gpen, Gdir)                      # index c = pen * 8 + dir
    if np.linalg.eigvalsh(G).min() < -1e-10:
        raise ValueError("token kernel is not positive semidefinite")
    return G


# --------------------------------------------------------------------------- statistics of data
def pair_index(d, lags):
    """All (t, s) with s - t in lags, as two int arrays."""
    T, S = [], []
    for lag in lags:
        for t in range(d - lag):
            T.append(t)
            S.append(t + lag)
    return np.array(T, dtype=np.int64), np.array(S, dtype=np.int64)


def data_statistics(C, K, kmax=3, lags=None):
    """Empirical window and pair laws of token sequences C (N, d) with tokens in 0..K-1."""
    C = np.asarray(C, dtype=np.int64)
    N, d = C.shape
    lags = list(range(kmax, d)) if lags is None else [int(l) for l in lags if kmax <= l < d]
    W = []
    for k in range(1, kmax + 1):
        idx = np.zeros((N, d - k + 1), dtype=np.int64)
        for j in range(k):
            idx = idx * K + C[:, j:d - k + 1 + j]
        Wk = np.zeros((d - k + 1, K ** k))
        for t in range(d - k + 1):
            Wk[t] = np.bincount(idx[:, t], minlength=K ** k)
        W.append((Wk / N).reshape((d - k + 1,) + (K,) * k))
    tI, sI = pair_index(d, lags)
    P = np.zeros((len(tI), K, K))
    for n, (t, s) in enumerate(zip(tI, sI)):
        P[n] = np.bincount(C[:, t] * K + C[:, s], minlength=K * K).reshape(K, K)
    return dict(d=d, K=K, kmax=kmax, lags=lags, W=W, pairs=P / N, pair_t=tI, pair_s=sI, N=N)


def independent_statistics(stats):
    """The same statistics for independent tokens with the data's one-point laws (the null)."""
    W1 = stats["W"][0]
    d, K = stats["d"], stats["K"]
    W = [W1]
    for k in range(2, stats["kmax"] + 1):
        Wk = W1[:d - k + 1].copy()
        for j in range(1, k):
            Wk = Wk[..., None] * W1[j:d - k + 1 + j].reshape((d - k + 1,) + (1,) * j + (K,))
        W.append(Wk)
    P = W1[stats["pair_t"]][:, :, None] * W1[stats["pair_s"]][:, None, :]
    return dict(stats, W=W, pairs=P)


# --------------------------------------------------------------------------- MMD of laws
def _kernel_apply(G, D):
    """(G x ... x G) D for D of shape (n, K, ..., K)."""
    k = D.ndim - 1
    out = D
    for ax in range(1, k + 1):
        out = np.moveaxis(np.tensordot(out, G, axes=([ax], [0])), -1, ax)
    return out


def mmd_terms(stats_model, stats_data, G, weights):
    """Per-statistic MMD^2 (windows k = 1..kmax, pairs) between two statistics dicts, and dL/dp."""
    lam = list(weights[:-1])
    lam_pair = weights[-1]
    vals, grads_W = {}, []
    loss = 0.0
    for k, (p, q) in enumerate(zip(stats_model["W"], stats_data["W"]), start=1):
        D = p - q
        M = _kernel_apply(G, D)
        per_t = (D * M).reshape(D.shape[0], -1).sum(1)
        vals[f"window{k}"] = float(per_t.mean())
        w = lam[k - 1] / D.shape[0]
        loss += lam[k - 1] * vals[f"window{k}"]
        grads_W.append(2.0 * w * M)
    Dp = stats_model["pairs"] - stats_data["pairs"]
    Mp = _kernel_apply(G, Dp)
    per_pair = (Dp * Mp).reshape(Dp.shape[0], -1).sum(1)
    vals["pairs"] = float(per_pair.mean()) if len(per_pair) else 0.0
    loss += lam_pair * vals["pairs"]
    grad_P = 2.0 * (lam_pair / max(len(per_pair), 1)) * Mp
    vals["pairs_by_lag"] = {int(l): float(per_pair[np.asarray(stats_model["pair_s"]) - np.asarray(stats_model["pair_t"]) == l].mean())
                            for l in stats_model["lags"]} if len(per_pair) else {}
    return float(loss), vals, grads_W, grad_P


# --------------------------------------------------------------------------- exact model statistics and gradient
def _forward(model, stats_ref, grad):
    """Exact window and pair laws of the model; with grad=True also the cache the backward pass needs."""
    d, K, kmax = model.d, model.K, stats_ref["kmax"]
    assert d == stats_ref["d"] and K == stats_ref["K"], "model and statistics disagree on d or K"
    tI, sI = stats_ref["pair_t"], stats_ref["pair_s"]
    ell = np.zeros(model._v0.size)
    ell[model._tr_idx] = 1.0
    lam, tapes = model.instruments_all(keep_tape=grad)          # (d, K, D, D); batched over rounds where available
    Dm = lam.shape[-1]
    T = lam.sum(axis=1)                                         # (d, D, D)
    r = np.zeros((d + 1, Dm), dtype=np.complex128)
    r[0] = model._v0
    for t in range(d):
        r[t + 1] = T[t] @ r[t]
    e = np.einsum("tcij,i->tcj", lam.conj(), ell)               # e[t,c] = Lambda^dagger ell  (D)
    # windows
    X1 = np.einsum("taij,tj->tai", lam, r[:d])                  # state after round t, per token a
    W = [np.real(np.einsum("tai,i->ta", X1, ell))]
    X2 = None
    if kmax >= 2:
        W.append(np.real(np.einsum("tbij,taj,i->tab", lam[1:], X1[:d - 1], ell)))
    if kmax >= 3:
        X2 = np.einsum("tbij,taj->tabi", lam[1:d - 1], X1[:d - 2])
        W.append(np.real(np.einsum("tcij,tabj,i->tabc", lam[2:], X2, ell)))
    if kmax >= 4:
        raise NotImplementedError("windows up to k = 3")
    # pairs: forward propagation from every t with a pair
    P = np.zeros((len(tI), K, K))
    by_t = {}
    for n, (t, s) in enumerate(zip(tI, sI)):
        by_t.setdefault(int(t), []).append((int(s), n))
    Xcache = {}
    for t, lst in by_t.items():
        smax = max(s for s, _ in lst)
        Xs = [X1[t]]                                            # Xs[u - t] = state after round u (per a)
        for u in range(t + 1, smax):
            Xs.append(Xs[-1] @ T[u].T)                          # T[u] X  for every row a
        for s, n in lst:
            P[n] = np.real(np.einsum("bij,aj,i->ab", lam[s], Xs[s - 1 - t], ell))
        if grad:
            Xcache[t] = Xs
    out = dict(stats_ref, W=W, pairs=P)
    if not grad:
        return out, None
    return out, dict(lam=lam, tapes=tapes, T=T, r=r, e=e, X1=X1, X2=X2, by_t=by_t, Xcache=Xcache, ell=ell, d=d, K=K, kmax=kmax, Dm=Dm)
def _backward(model, cache, grad_W, grad_P):
    """dL/d(parameters) from dL/d(laws), reusing the forward cache."""
    lam, tapes, T, r, e, X1, X2 = (cache[k] for k in ('lam', 'tapes', 'T', 'r', 'e', 'X1', 'X2'))
    by_t, Xcache, ell, d, K, kmax, Dm = (cache[k] for k in ('by_t', 'Xcache', 'ell', 'd', 'K', 'kmax', 'Dm'))
    G_lam = np.zeros_like(lam)
    GX1 = np.zeros_like(X1)
    Gr = np.zeros_like(r)
    gW = grad_W
    if kmax >= 3:
        g3 = gW[2]
        G_lam[2:] += np.einsum("tabc,i,tabj->tcij", g3, ell, X2.conj())
        GX2 = np.einsum("tabc,tcj->tabj", g3, e[2:])
        G_lam[1:d - 1] += np.einsum("tabi,taj->tbij", GX2, X1[:d - 2].conj())
        GX1[:d - 2] += np.einsum("tbij,tabi->taj", lam[1:d - 1].conj(), GX2)
    if kmax >= 2:
        g2 = gW[1]
        G_lam[1:] += np.einsum("tab,i,taj->tbij", g2, ell, X1[:d - 1].conj())
        GX1[:d - 1] += np.einsum("tab,tbj->taj", g2, e[1:])
    g1 = gW[0]
    G_lam += np.einsum("ta,i,tj->taij", g1, ell, r[:d].conj())
    Gr[:d] += np.einsum("ta,taj->tj", g1, e)
    # pairs
    for t, lst in by_t.items():
        Xs = Xcache[t]
        smax = max(s for s, _ in lst)
        gp = {s: grad_P[n] for s, n in lst}
        GX = np.zeros((K, Dm), dtype=np.complex128)             # dL/dX^{(u)} for the current u
        for u in range(smax - 1, t - 1, -1):
            if u + 1 < smax:                                     # X^{(u+1)} = T[u+1] X^{(u)} was used
                G_lam[u + 1] += np.einsum("ai,aj->ij", GX, Xs[u - t].conj())[None]
                GX = np.einsum("ji,aj->ai", T[u + 1].conj(), GX)
            if (u + 1) in gp:                                   # emission at round u + 1 read X^{(u)}
                g = gp[u + 1]
                G_lam[u + 1] += np.einsum("ab,i,aj->bij", g, ell, Xs[u - t].conj())
                GX += np.einsum("ab,bj->aj", g, e[u + 1])
        GX1[t] += GX
    # X1[t] = Lambda_t r_t
    G_lam += np.einsum("tai,tj->taij", GX1, r[:d].conj())
    Gr[:d] += np.einsum("taij,tai->tj", lam.conj(), GX1)
    # forward chain r[t+1] = T[t] r[t]
    for t in range(d - 1, -1, -1):
        G_lam[t] += np.outer(Gr[t + 1], r[t].conj())[None]
        Gr[t] += T[t].conj().T @ Gr[t + 1]
    # instruments -> parameters
    g_inst = model.instruments_all_vjp(tapes, G_lam)
    gh = np.zeros_like(model.h)
    return np.concatenate([g.ravel() for g in g_inst] + [gh.ravel()])


def model_statistics(model, stats_ref, grad=False, grad_W=None, grad_P=None):
    """Exact window and pair laws of the model for the statistics layout of stats_ref.
    With grad=True also returns dL/d(parameters) for the given dL/dp (grad_W: list per k, grad_P)."""
    out, cache = _forward(model, stats_ref, grad)
    return (out, None) if not grad else (out, _backward(model, cache, grad_W, grad_P))




def kpoint_loss(model, stats_data, G, weights, grad=True):
    """Loss, per-term values and (optionally) the exact gradient wrt model.get()."""
    sm, cache = _forward(model, stats_data, grad)
    loss, vals, gW, gP = mmd_terms(sm, stats_data, G, weights)
    if not grad:
        return loss, vals, None
    return loss, vals, _backward(model, cache, gW, gP)


# --------------------------------------------------------------------------- training
def train_kpoint(model, stats_train, stats_val, G, weights=(1.0, 1.0, 1.0, 1.0), steps=1500, lr=0.05,
                 warmup=50, val_every=25, log=print, ckpt=None, extra=None, extra_val=None, resume=True):
    """Adam on the exact k-point MMD; model selection on the validation statistics.
    extra(model, step) -> (loss, grad) adds a further term (e.g. the path MMD of comb/pencf.py) to every
    step, and extra_val(model) -> loss adds its validation value to the selection criterion.
    With resume=True and an existing checkpoint, training continues from it: parameters, Adam moments,
    best model and history are restored, so an interrupted run ends exactly where an uninterrupted one would
    (given an extra term whose randomness is seeded by the step)."""
    p = model.get()
    adam = Adam(p.size)
    hist = dict(step=[], loss=[], val=[], time=[])
    t0 = time.time()
    best_val, best_p, best_step, start = np.inf, p.copy(), 0, 0
    if resume and ckpt is not None and pathlib.Path(str(ckpt)).exists():
        c = np.load(ckpt, allow_pickle=True)
        if "adam_m" in c.files and c["p"].size == p.size and int(c["steps"]) == steps:
            p, best_p, best_val, best_step = c["p"].copy(), c["best_p"].copy(), float(c["best_val"]), int(c["best_step"])
            adam.m, adam.v, adam.t = c["adam_m"].copy(), c["adam_v"].copy(), int(c["adam_t"])
            hist = json.loads(str(c["hist"]))
            start = int(c["step"])
            t0 -= hist["time"][-1] if hist["time"] else 0.0
            model.set(p)
            if log:
                log(f"resumed from step {start} (best {best_val:.3e} at {best_step})")
    for step in range(start, steps + 1):
        loss, vals, g = kpoint_loss(model, stats_train, G, weights, grad=True)
        if extra is not None:
            le, ge = extra(model, step)
            loss += le
            g = g + ge
        if (step % val_every == 0 or step == steps) and not (step == start and start > 0):
            val, vvals, _ = kpoint_loss(model, stats_val, G, weights, grad=False)
            if extra_val is not None:
                vvals["path"] = extra_val(model)
                val += vvals["path"]
            hist["step"].append(step)
            hist["loss"].append(loss)
            hist["val"].append(val)
            hist["time"].append(time.time() - t0)
            if val < best_val:
                best_val, best_p, best_step = val, p.copy(), step
            if log:
                log(f"step {step:5d}  train {loss:.3e}  val {val:.3e}  (windows {vvals['window1']:.2e}/{vvals.get('window2', 0):.2e}/"
                    f"{vvals.get('window3', 0):.2e}  pairs {vvals['pairs']:.2e}  path {vvals.get('path', 0):.2e})  best {best_val:.3e}@{best_step}  {time.time() - t0:.0f}s")
            if ckpt is not None:
                np.savez(ckpt, p=p, best_p=best_p, best_val=best_val, best_step=best_step, step=step, steps=steps,
                         adam_m=adam.m, adam_v=adam.v, adam_t=adam.t, hist=json.dumps(hist))
        if step == steps:
            break
        p = adam.step(p, g, lr_at(step, steps, lr, warmup))
        model.set(p)
    model.set(best_p)
    return dict(hist=hist, best_val=float(best_val), best_step=int(best_step), steps=steps, train_time=time.time() - t0)
